window.blogDetail = {"blogId":1530456338,"blogType":0,"pubTime":"2018-07-01 22:45","sLastModifyTime":"2018-07-01 23:02","lastModifyTime":1530457321,"cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"行走在浪漫中的大唐谪仙—— “诗仙”李白","commentNum":0,"effect1":1025,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"“酒入豪肠，七分酿成了月光，余下的三分，啸成了剑气，绣口一吐，便是半个盛唐”。提及李白，就不得不令人想起余光中先生的这首诗。风流倜傥，狂放不羁，是我们对他的整体印象。有人说他是一位侠客，仗剑去国，辞亲远游只是为了一展豪情；有人说他是一名谪仙，是天上的太白星，用自己的光芒照亮了整个盛唐。他的一生带有非常浓厚的传奇色彩：“力士脱靴”，“贵妃研墨”，“抱月而归”这些耳熟能详的典故铸就了他一生的浪漫，而那...","img":[{"url":"https://a1.qpic.cn/psb?/V115Q4qb1YRbBN/BA*.Y55L6tBxO**1obeb*ZmUrVhmPdrQE4GRGhrhKF8!/c/dPQAAAAAAAAA&ek=1&kp=1&pt=0&bo=.QAsAQAAAAAREPM!&tl=1&su=0135498993&tm=1779170400&dis_t=1779172628&dis_k=c57ca32a720f38a793fcd419e275b3e8&sce=0-12-12&rf=0-2-8","custom_url":"images/F8FC141F.jpeg"},{"url":"https://a4.qpic.cn/psb?/V115Q4qb1YRbBN/dOJqvmbdtWOw5*Jn.fYfLIKSzQizr1mPOWKR9*m.BO0!/c/dN8AAAAAAAAA&ek=1&kp=1&pt=0&bo=gAKoAQAAAAAREAw!&tl=1&su=0112947281&tm=1779170400&dis_t=1779172628&dis_k=684446fb0c51b54a1855b9cd67bc7475&sce=0-12-12&rf=0-2-8","custom_url":"images/2D9F1ADE.jpeg"}],"artype":1,"arUins":"","blogid":1530456338,"voteids":0,"pubtime":1530457321,"replynum":0,"category":"个人日记","effect":1025,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1530456338,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"行走在浪漫中的大唐谪仙—— “诗仙”李白","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1530456338"}